const items = $input.all();

return items.map(item => {
  const raw = item.json.output;

  if (!raw) {
    throw new Error("AI Agent returned an empty output.");
  }

  // Remove optional Markdown JSON fences.
  const cleaned = typeof raw === "string"
    ? raw.trim()
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/i, "")
    : null;

  let review;

  try {
    review = cleaned
      ? JSON.parse(cleaned)
      : raw;
  } catch (error) {
    throw new Error(
      "Invalid JSON from AI Agent: " + error.message
    );
  }

  // Validate the rating.
  const rating = Number(review.rating);

  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    throw new Error("Invalid review rating: " + review.rating);
  }

  // Enforce the rating policy in the workflow.
  const decision = rating === 1
    ? "MANUAL_REVIEW_REQUIRED"
    : "AUTOMATIC_REPLY";

  const publicReply = rating === 1
    ? null
    : review.public_reply;

  if (rating >= 2 &&
      (typeof publicReply !== "string" || !publicReply.trim())) {
    throw new Error("Missing public reply for rating " + rating);
  }

  return {
    json: {
      rating,
      sentiment: review.sentiment,
      customer_concerns: review.customer_concerns,
      decision,
      internal_assessment: review.internal_assessment,
      public_reply: publicReply,
      raw_output: raw
    }
  };
});

const items = $input.all();

// Retrieve the original parsed review from the Code node
// BEFORE the Switch and Guardrails.
const originalReview = $('Parse Review JSON').first().json;

// Change to "failure" later to test Google API errors.
const MOCK_MODE = "success";

return items.map(item => {
  const guardrailResult = item.json;
  const review = originalReview;

  // Make sure the original review data is available.
  if (!review || !review.rating) {
    throw new Error("Original review data could not be retrieved.");
  }

  const rating = Number(review.rating);

  // Only allow automatic replies for ratings 2–5.
  if (!Number.isInteger(rating) || rating < 2 || rating > 5) {
    throw new Error("Invalid rating for automatic reply.");
  }

  if (review.decision !== "AUTOMATIC_REPLY") {
    throw new Error("Review is not authorized for automatic reply.");
  }

  if (
    typeof review.public_reply !== "string" ||
    !review.public_reply.trim()
  ) {
    throw new Error("Public reply is missing.");
  }

  // Verify that Guardrails did not detect a violation.
  const checks = guardrailResult.checks || [];

  const violations = checks.filter(
    check => check.triggered === true
  );

  if (violations.length > 0) {
    throw new Error("Guardrails detected violations.");
  }

  const simulateFailure = MOCK_MODE === "failure";

  const mockReviewId = `mock-review-${rating}-001`;

  const mockReviewName =
    `accounts/MOCK_ACCOUNT/locations/MOCK_LOCATION/reviews/${mockReviewId}`;

  const mockResponse = simulateFailure
    ? null
    : {
        comment: review.public_reply,
        updateTime: new Date().toISOString()
      };

  return {
    json: {
      ...review,

      guardrails_passed: true,
      guardrails_checks: checks,

      google_api_mode: "MOCK",
      google_api_success: !simulateFailure,
      google_api_http_status: simulateFailure ? 503 : 200,

      mock_review_id: mockReviewId,
      mock_review_name: mockReviewName,

      mock_google_reply_response: mockResponse,

      google_api_error: simulateFailure
        ? "Simulated temporary Google API service failure."
        : null,

      google_reply_published: false,

      google_reply_status: simulateFailure
        ? "SIMULATED_FAILURE"
        : "SIMULATED_SUCCESS"
    }
  };
});

