const items = $input.all();

// Read the original chat message.
const chatText =
  $('Test Review Input').first().json.chatInput || '';

// Extract the synthetic review ID.
const match = chatText.match(
  /^\s*Review ID:\s*(.+?)\s*$/im
);

if (!match) {
  throw new Error(
    'Missing Review ID. Include a line such as Review ID: TEST-001'
  );
}

const reviewId = match[1].trim();

if (!reviewId) {
  throw new Error('Review ID cannot be empty.');
}

return items.map(item => ({
  json: {
    ...item.json,

    review_id: reviewId,
    status: 'RECEIVED',
    rating: Number(item.json.rating),
    first_seen_at: new Date().toISOString(),
    source: 'CHAT_TEST'
  }
}));

const insertedRows = $input.all();

// Retrieve the complete review data from before
// the Data Table insertion.
const originalReview = $('Assign Review ID').first().json;

return insertedRows.map(item => ({
  json: {
    ...originalReview,
    ...item.json
  }
}));
